import{_ as p,a0 as u,w as o,s as r,I as a,x as i,a1 as s,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"安裝 Ubuntu 22.10 後要做的 10 件事 | LCTT x X-CMD","titleTemplate":false,"description":"安裝 Ubuntu 22.10 後要做的 10 件事 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安裝 Ubuntu 22.10 後要做的 10 件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安裝 Ubuntu 22.10 後要做的 10 件事 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221021.2 ⭐️⭐️  10 Things to Do After Installing Ubuntu 22.10 [With Bonus Tip]","title":"安裝 Ubuntu 22.10 後要做的 10 件事","tag":"202210","desc":""},"relativePath":"202210/20221021.2 ⭐️⭐️  10 Things to Do After Installing Ubuntu 22.10 [With Bonus Tip].md","filePath":"[post].md"}'),d={name:"202210/20221021.2 ⭐️⭐️  10 Things to Do After Installing Ubuntu 22.10 [With Bonus Tip].md"};function b(h,t,g,f,k,m){const e=u("Link");return o(),r("div",null,[t[32]||(t[32]=a("h1",{id:"安裝-ubuntu-22-10-後要做的-10-件事",tabindex:"-1"},[i("安裝 Ubuntu 22.10 後要做的 10 件事 "),a("a",{class:"header-anchor",href:"#安裝-ubuntu-22-10-後要做的-10-件事","aria-label":"Permalink to “安裝 Ubuntu 22.10 後要做的 10 件事”"},"​")],-1)),t[33]||(t[33]=a("blockquote",null,[a("p",null,"以下是我們安裝 Ubuntu 22.10 “Kinetic Kudu”（GNOME 版）後，推薦做的 10 件事列表。")],-1)),t[34]||(t[34]=a("p",null,[a("img",{src:"https://www.debugpoint.com/wp-content/uploads/2022/10/u2210-things-hd-1024x576.jpg",alt:""})],-1)),a("p",null,[t[1]||(t[1]=i("Ubuntu 22.10 帶來了很多令人興奮的新功能，例如 GNOME 43、最新的內核、重新設計的托盤菜單、文件應用的功能和 Pipewire 等 ",-1)),s(e,{href:"https://www.debugpoint.com/ubuntu-22-10/"},{default:n(()=>[...t[0]||(t[0]=[i("新功能",-1)])]),_:1}),t[2]||(t[2]=i("。",-1))]),t[35]||(t[35]=l('<p>我相信你已經迫不及待地想嘗試 Ubuntu 22.10 上的這些新功能了。</p><p>但是請先等一等。</p><p>在你前往享受你新安裝的 Ubuntu 22.10 之前，我要向你推薦一個不容錯過的 Ubuntu 定製技巧列表。</p><h3 id="安裝-ubuntu-22-10-後要做的-10-件事-1" tabindex="-1">安裝 Ubuntu 22.10 後要做的 10 件事 <a class="header-anchor" href="#安裝-ubuntu-22-10-後要做的-10-件事-1" aria-label="Permalink to “安裝 Ubuntu 22.10 後要做的 10 件事”">​</a></h3><h4 id="_1、更新你的系統" tabindex="-1">1、更新你的系統 <a class="header-anchor" href="#_1、更新你的系統" aria-label="Permalink to “1、更新你的系統”">​</a></h4><p>安裝好 Ubuntu 22.10 後，第一件要做的事就是更新你的系統。因為時差的原因，最新的 ISO 鏡像通常不會包括所有的系統更新。所以，你要打開一個終端窗口，並運行以下命令，來更新你的系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade</span></span></code></pre></div><p>上述命令執行完成後，你就可以進行下一步啦。</p><h4 id="_2、刪除-firefox-snap-並安裝-flatpak-或者-deb-版本的-firefox" tabindex="-1">2、刪除 Firefox Snap，並安裝 Flatpak 或者 deb 版本的 Firefox <a class="header-anchor" href="#_2、刪除-firefox-snap-並安裝-flatpak-或者-deb-版本的-firefox" aria-label="Permalink to “2、刪除 Firefox Snap，並安裝 Flatpak 或者 deb 版本的 Firefox”">​</a></h4><p>自去年發佈的 Ubuntu 21.10 版本以來，默認的網頁瀏覽器 Firefox 開始以 Snap 軟件包的形式出現。如果你是普通用户，這可能不是一個問題或者需要擔心的事情。但是出於幾個原因，例如 Snap 軟件包的 Firefox 啓動時間較長、且當 Firefox 有後台更新時，會有不必要的 Snap 更新通知等等原因，導致許多用户不太喜歡 Firefox 的 Snap 軟件包。</p>',10)),a("p",null,[t[5]||(t[5]=i("因此，你可以按照 ",-1)),s(e,{href:"https://www.debugpoint.com/remove-firefox-snap-ubuntu/"},{default:n(()=>[...t[3]||(t[3]=[i("我寫的另一篇操作指南",-1)])]),_:1}),t[6]||(t[6]=i("，來完全刪除 Firefox 的 Snap 軟件包。這一過程有點複雜，需要花費一點時間。刪除完成後，再從個人軟件包存檔（PPA）安裝 deb 版本的 Firefox，或者使用 ",-1)),s(e,{href:"https://flathub.org/apps/details/org.mozilla.firefox"},{default:n(()=>[...t[4]||(t[4]=[i("Flatpak 版本",-1)])]),_:1}),t[7]||(t[7]=i(" 的 Firefox。",-1))]),t[36]||(t[36]=l('<p>這是一個可選的動作，你也可以跳過這一步驟。</p><h4 id="_3、安裝並啓用-flatpak" tabindex="-1">3、安裝並啓用 Flatpak <a class="header-anchor" href="#_3、安裝並啓用-flatpak" aria-label="Permalink to “3、安裝並啓用 Flatpak”">​</a></h4><p>雖然，幾乎所有最新的 Linux 發行版都會默認安裝 Flatpak，但是 Ubuntu 並沒有默認安裝 Flatpak，這是因為 Ubuntu 使用了它自己的沙箱技術 Snap。</p><p>但 Flatpak 這一應用程序還是最適合於每個人。Flatpak 能夠幫助你快速安裝多個應用程序，並在使用過程中無需擔心依賴性和其他事情。</p><p>大多數 Flatpak 應用程序都在集中的倉庫 Flathub 中。</p><p>要在 Ubuntu 22.10 中啓用 Flatpak 應用程序，請按照以下命令進行操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install flatpakflatpak remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakreporeboot</span></span></code></pre></div>',7)),a("p",null,[t[9]||(t[9]=i("如果你想進一步瞭解關於此安裝過程的更多信息，請閲讀我們不久前發佈的 ",-1)),s(e,{href:"https://www.debugpoint.com/how-to-install-flatpak-apps-ubuntu-linux/"},{default:n(()=>[...t[8]||(t[8]=[i("指南",-1)])]),_:1}),t[10]||(t[10]=i("。",-1))]),t[37]||(t[37]=l('<h4 id="_4、查看隱私設置" tabindex="-1">4、查看隱私設置 <a class="header-anchor" href="#_4、查看隱私設置" aria-label="Permalink to “4、查看隱私設置”">​</a></h4><p>我建議你在安裝 Ubuntu 後，手動退出任何數據收集項。大家都知道，無論怎麼努力嘗試，在互聯網上保護自己的隱私都很困難。因此，這些小步驟很重要。</p><p>要配置隱私項，請打開“<ruby>設置<rt>Settings</rt></ruby>”並選擇“<ruby>隱私<rt>Privacy</rt></ruby>”。然後查看隱私菜單下列出的項目。</p><p>此外，請確保禁用對 Ubuntu 服務器的後台報告。需要運行以下命令來手動禁用，因為在設置中沒有禁用它的選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ubuntu-report -f send no</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/Turn-off-location-services-in-Ubuntu-22.10.jpg" alt="Turn off location services in Ubuntu 22.10"></p><h4 id="_5、探索-gnome-43-的功能" tabindex="-1">5、探索 GNOME 43 的功能 <a class="header-anchor" href="#_5、探索-gnome-43-的功能" aria-label="Permalink to “5、探索 GNOME 43 的功能”">​</a></h4><p>在 Ubuntu 22.10 版本中，最具視覺和功能性的變化是 GNOME 43。因為 GNOME 43 有一些根本性和核心變化，所以它會影響每個人和他們的工作。GNOME 43 帶來了一個新的藥丸形狀的托盤菜單，並更新了文件應用和 GNOME Web 等原生應用程序的功能。</p>',8)),a("p",null,[t[12]||(t[12]=i("請查看更為詳細的 ",-1)),s(e,{href:"https://www.debugpoint.com/gnome-43/"},{default:n(()=>[...t[11]||(t[11]=[i("GNOME 43 功能",-1)])]),_:1}),t[13]||(t[13]=i(" 一文，以瞭解更多信息，或者你也可以自己探索 GNOME 43。",-1))]),t[38]||(t[38]=l('<p><img src="https://www.debugpoint.com/wp-content/uploads/2022/08/Quick-Settings-Demo-in-GNOME-43.gif" alt="Quick Settings Demo in GNOME 43"></p><h4 id="_6、確保音頻可以與-pipewire-配合使用" tabindex="-1">6、確保音頻可以與 Pipewire 配合使用 <a class="header-anchor" href="#_6、確保音頻可以與-pipewire-配合使用" aria-label="Permalink to “6、確保音頻可以與 Pipewire 配合使用”">​</a></h4><p>如果你經常使用音頻，或者你的工作範圍涉及到聲音捕獲、播放等內容，請確保在 Ubuntu 22.10 中，你的音頻在有線或藍牙情況下都能正常工作。</p><p>因為 Ubuntu 22.10 這個版本中的音頻服務器是多年來第一次發生了變化，傳統的 PulseAudio 被現代的 Pipewire 所取代。因此，請務必進行驗證音頻是否能正常使用。</p><h4 id="_7、安裝其他軟件包" tabindex="-1">7、安裝其他軟件包 <a class="header-anchor" href="#_7、安裝其他軟件包" aria-label="Permalink to “7、安裝其他軟件包”">​</a></h4><p>確保你可以在 Ubuntu 桌面上播放所有視頻和音頻格式是很重要的。如果你在設置期間跳過了額外的軟件包安裝，可以通過以下命令進行安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install ubuntu-restricted-extras</span></span></code></pre></div><p>這可以解決 Ubuntu 中的任何視頻或音頻的播放問題，特別是 GNOME 視頻無法播放的情況（因為GNOME 視頻在默認情況下將無法播放任何內容）。</p><h4 id="_8、安裝基本的應用程序" tabindex="-1">8、安裝基本的應用程序 <a class="header-anchor" href="#_8、安裝基本的應用程序" aria-label="Permalink to “8、安裝基本的應用程序”">​</a></h4><p>帶有 GNOME 的 Ubuntu 基礎版本只有非常基本的應用程序。因此，在你使用 Ubuntu 之前，你需要安裝一些其他必要的應用程序。</p><p>由於每個人的工作範圍不同，每個人所需的應用程序也都不同。因此，在這裏我僅提供一個通用的應用程序的列表，我認為你可以把這些應用程序都安裝上，因為這些應用程序對所有人來説都很常用。</p><ul><li>GIMP – 進階的照片編輯器</li><li>VLC – 無需額外編解碼器即可播放任何內容的媒體播放器</li><li>Leafpad – 輕量級文本編輯器（甚至比默認的文本編輯器 gedit 還要更輕量級）</li><li>Synaptic – 更好的軟件包管理器</li></ul><p>安裝這些應用程序的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install -y gimp vlc leafpad synaptic</span></span></code></pre></div><h4 id="_9、獲取一些-gnome-擴展" tabindex="-1">9、獲取一些 GNOME 擴展 <a class="header-anchor" href="#_9、獲取一些-gnome-擴展" aria-label="Permalink to “9、獲取一些 GNOME 擴展”">​</a></h4><p>你可以使用幾個很酷的擴展程序，來擴展 GNOME 43 的功能，包括自定義頂部欄、托盤、更改 adwaita 外觀等等。首先，使用下面的命令通過 Flatpak 來安裝 GNOME 擴展管理器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install flathub com.mattjakeman.ExtensionManager</span></span></code></pre></div><p>安裝完成後，你就可以在 GNOME 擴展管理器中搜索你想要的任何擴展了。以下是一些必要擴展，你可以用它們來快速擴展 GNOME 43 的功能，我認為它們非常適合你全新的 Ubuntu 桌面。你只需在擴展管理器應用程序中，搜索這些名稱即可。</p><ul><li>Caffeine</li><li>Custom Hot Corners</li><li>Dash to Dock</li><li>Blur my shell</li><li>Gradients</li><li>Hide Activities Button</li><li>Net speed simplified</li></ul><h4 id="_10、準備備份" tabindex="-1">10、準備備份 <a class="header-anchor" href="#_10、準備備份" aria-label="Permalink to “10、準備備份”">​</a></h4><p>我們總是在我們遇到困難時，才覺得有必要備份。所以，請確保從一開始你就為備份做好了準備。理想的備份應用程序是 Timeshift，它很容易安裝和使用。</p><p>以下是你可以從終端安裝 Timeshift 的一組命令。安裝完成後，你可以打開 Timeshift，並按照屏幕上的説明，設置備份了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository -y ppa:teejee2008/ppasudo apt-get updatesudo apt-get install timeshift</span></span></code></pre></div><h3 id="額外小技巧" tabindex="-1">額外小技巧 <a class="header-anchor" href="#額外小技巧" aria-label="Permalink to “額外小技巧”">​</a></h3><p>如果你想進一步定製你新安裝的 Ubuntu 系統，以下是一些額外的小技巧。</p><h4 id="安裝漂亮的字體" tabindex="-1">安裝漂亮的字體 <a class="header-anchor" href="#安裝漂亮的字體" aria-label="Permalink to “安裝漂亮的字體”">​</a></h4><p>字體是一個很小卻影響很大的設置項。雖然，Ubuntu 自帶有好用的“Ubuntu regular”字體。</p><p>但是，你也可以從 Ubuntu 的官方倉庫中安裝一些其他漂亮的字體。以下是安裝字體的一些命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install fonts-roboto fonts-cascadia-code fonts-firacode</span></span></code></pre></div>',29)),a("p",null,[t[15]||(t[15]=i("安裝完成後，你可以使用 ",-1)),s(e,{href:"https://www.debugpoint.com/customize-your-ubuntu-desktop-using-gnome-tweak/"},{default:n(()=>[...t[14]||(t[14]=[i("GNOME Tweak 工具",-1)])]),_:1}),t[16]||(t[16]=i("，來更改字體。",-1))]),t[39]||(t[39]=l('<h4 id="安裝-tlp" tabindex="-1">安裝 TLP <a class="header-anchor" href="#安裝-tlp" aria-label="Permalink to “安裝 TLP”">​</a></h4><p>如果你經常使用筆記本電腦，那麼你要好好愛惜電腦的電池。雖然電池用久了總是會損壞的，但你可以採取一些步驟，來減緩電池的老化。TLP 是 Linux 中自動優化電池使用、減緩電池老化的最好的程序之一。你可以使用以下命令來安裝 TLP。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install tlp</span></span></code></pre></div><p>我建議你將電池的電量始終保持在 50% 至 80% 之間。不要過度充電或讓電池電量消耗到 50% 以下，也不要給電腦連續插電。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>以上就是安裝桌面 Ubuntu 22.10 後要做的 10 件事啦。</p><p>我希望這篇文章會對你有幫助，你能夠通過本文的方法來定製和調整你的 Ubuntu 桌面。那麼你認為在安裝好 Ubuntu 後，什麼事是最推薦做的呢？請在評論區中告訴我吧。</p><hr>',8)),a("p",null,[t[18]||(t[18]=i("via: ",-1)),s(e,{href:"https://www.debugpoint.com/things-to-do-ubuntu-22-10/"},{default:n(()=>[...t[17]||(t[17]=[i("https://www.debugpoint.com/things-to-do-ubuntu-22-10/",-1)])]),_:1})]),a("p",null,[t[23]||(t[23]=i("作者：",-1)),s(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...t[19]||(t[19]=[i("Arindam",-1)])]),_:1}),t[24]||(t[24]=i(" 選題：",-1)),s(e,{href:"https://github.com/lkxed"},{default:n(()=>[...t[20]||(t[20]=[i("lkxed",-1)])]),_:1}),t[25]||(t[25]=i(" 譯者：",-1)),s(e,{href:"https://github.com/chai001125"},{default:n(()=>[...t[21]||(t[21]=[i("chai001125",-1)])]),_:1}),t[26]||(t[26]=i(" 校對：",-1)),s(e,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:n(()=>[...t[22]||(t[22]=[i("校對者ID",-1)])]),_:1})]),a("p",null,[t[29]||(t[29]=i("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[27]||(t[27]=[i("LCTT",-1)])]),_:1}),t[30]||(t[30]=i(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:n(()=>[...t[28]||(t[28]=[i("Linux中國",-1)])]),_:1}),t[31]||(t[31]=i(" 榮譽推出",-1))])])}const _=p(d,[["render",b]]);export{w as __pageData,_ as default};
